<?php if($page!=='login'):?><aside class="sidebar"><a class="brand" href="<?=e(url('dashboard'))?>"><span class="brand-mark">CV</span><span>Control<br><strong>vehicular</strong></span></a><div class="nav-caption">ADMINISTRACIÓN</div><nav><?php foreach(['dashboard'=>['Panel de vehículos','◫'],'vehicles'=>['Vehículos','▣'],'reservations'=>['Programación','▦'],'reports'=>['Concentrados','▤'],'gaps'=>['Kilómetros pendientes','↔'],'import'=>['Importar registros','↥']] as $p=>$n):?><a class="<?=$page===$p?'active':''?>" href="<?=e(url($p))?>"><span aria-hidden="true"><?=e($n[1])?></span><?=e($n[0])?></a><?php endforeach;?></nav><div class="side-bottom"><span>Bitácoras y combustible</span><small>Versión 1.1</small><form method="post"><?=csrf()?><input type="hidden" name="action" value="logout"><button class="logout">Cerrar sesión</button></form></div></aside><?php endif;?>
